from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple, TypeVar

@dataclass
class Point:
    x: float
    y: float

T = TypeVar('T')

def point_type(name: str, fields: Iterable[str], srid_map: Dict[str, T]) -> type:
    """Dynamically create a Point subclass."""

    if name is None:
        name = 'Point'

    if fields is None:
        fields = ['x', 'y']

    annotations = {field: float for field in fields}
    namespace = {
        'x': field(default_factory=float),
        'y': field(default_factory=float),
        'srid': field(default_factory=lambda: next(iter(srid_map.values())))
    }

    for field_name in fields:
        if field_name not in annotations:
            annotations[field_name] = float
            namespace[field_name] = field(default_factory=float)

    cls = types.new_class(name, (Point,), {'__annotations__': annotations}, lambda ns: ns.update(namespace))
    return dataclass(cls)

