import numpy as np

class Histogram:
    def __init__(self, edges, weights=None):
        self.edges = edges
        if weights is None:
            weights = np.ones_like(edges) - np.concatenate(([0], edges[:-1]))
        self.weights = weights
        self.values = np.zeros(len(edges) - 1)

    def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        index = np.searchsorted(self.edges, coord, side='right')
        if index > 0 and index < len(self.edges):
            self.values[index - 1] += weight * self.weights[index]

