    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors: List[Dict[str, str]] = []

    # Regex for valid label keys and values
    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]*$')

    for key, value in labels.items():
        if isinstance(key, str):
            if not key_regex.match(key):
                errors.append({key: "Label key does not match the regex"})
        elif isinstance(key, list):
            for item in key:
                if isinstance(item, str):
                    if not key_regex.match(item):
                        errors.append({item: "Label key does not match the regex"})
                else:
                    errors.append({str(item): "expected string or bytes-like object"})
        else:
            errors.append({key: "expected string or bytes-like object"})

        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: "Label value does not match the regex"})
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, str):
                    if not value_regex.match(item):
                        errors.append({item: "Label value does not match the regex"})
                else:
                    errors.append({str(item): "expected string or bytes-like object"})
        else:
            errors.append({value: "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

