    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = []

    for file in manifest_files:
        with open(file, 'r') as f:
            content = f.read()
            for line in content.splitlines():
                if line.startswith('digest='):
                    digest = line.split('=')[1].strip()
                    if digest not in digests_used:
                        missing_digests.append(digest)
                    else:
                        digests_used.remove(digest)

    if not digests_used:
        return missing_digests, unused_digests, "All digests are present and used."
    else:
        unused_digests.extend(digests_used)
        return missing_digests, unused_digests, "Some digests are present but not used."

