import argparse

class ExpressionAgent:
    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

        def apply_absorption(expression):
            # Apply absorption laws
            if expression.count('&') > 1 and expression.count('|') > 1:
                if expression.endswith('&') or expression.startswith('&'):
                    parts = expression.split('&')
                    for part in parts:
                        if part.endswith(') |') or part.startswith('| ('):
                            return '(' + part.strip('()') + ')'
            return expression

        def apply_negative_absorption(expression):
            # Apply negative absorption laws
            if expression.count('&') > 1 and expression.count('|') > 1:
                if expression.endswith('&') or expression.startswith('&'):
                    parts = expression.split('&')
                    for part in parts:
                        if part.endswith(') | not') or part.startswith('not | ('):
                            return '(' + part.strip('()') + ')'
            return expression

        new_args = []
        for arg in args:
            abs_arg = apply_absorption(arg)
            neg_abs_arg = apply_negative_absorption(abs_arg)
            new_args.append(neg_abs_arg)

        return new_args

