from hashlib import sha256

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for root, dirs, files in os.walk(self.storage_root):
        for file in files:
            file_path = os.path.join(root, file)
            num_objects += 1
            try:
                with open(file_path, 'rb') as f:
                    file_content = f.read()
                    if check_digests:
                        file_digest = sha256(file_content).hexdigest()
                        stored_digest = self._read_digest(file_path)
                        if file_digest != stored_digest:
                            if show_warnings:
                                print(f"Warning: Digest mismatch for {file_path}")
                            continue
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Error processing {file_path}: {e}")

    return num_objects, good_objects

