def validate_version_inventories(self, version_dirs):
    """Each version should have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    different_digests = {}

    # Load root inventory
    root_inventory_file = os.path.join(version_dirs[0], 'inventory.json')
    if os.path.exists(root_inventory_file):
        with open(root_inventory_file, 'r') as f:
            root_inventory = json.load(f)

    # Validate each version inventory
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_file):
            raise ValueError(f"Inventory file not found for version {version_dir}")

        with open(inventory_file, 'r') as f:
            inventory = json.load(f)

        # Check if the inventory is up to date
        if not all(item in root_inventory for item in inventory):
            raise ValueError(f"Inventory for version {version_dir} is not up to date")

        # Check for different content digests
        for item, content in inventory.items():
            if item in root_inventory and content['digest'] != root_inventory[item]['digest']:
                different_digests[item] = content['digest']

    return different_digests

