import re
import platform as p

def shlex_split(s, platform='this'):
    if platform == 'this':
        platform = p.system()

    if platform == 'Windows':
        pattern = re.compile(r'("(?:[^"\\]*(?:\\.[^"\\]*)*")|[^\s\\]+')
    else:
        pattern = re.compile(r'"([^"\\]*(?:\\.[^"\\]*)*)"|\'([^\']*?)\'|[^\s\']+')

    return pattern.findall(' ' + s + ' ')

