from pathlib import PosixPath, Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    # Ensure tmp_path is a PosixPath
    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    # Create a temporary directory to extract the archive
    extract_path = tmp_path / 'extracted_repo'
    extract_path.mkdir(parents=True, exist_ok=True)

    # Uncompress the archive
    if archive_path.endswith('.tar.gz'):
        command = ['tar', '-zxvf', archive_path, '-C', str(extract_path)]
    elif archive_path.endswith('.tar.bz2'):
        command = ['tar', '-xjvf', archive_path, '-C', str(extract_path)]
    elif archive_path.endswith('.zip'):
        command = ['unzip', archive_path, '-d', str(extract_path)]
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    subprocess.run(command, check=True)

    # Construct the file repo URL
    if filename:
        file_path = extract_path / filename
    else:
        file_path = next(extract_path.iterdir())

    return file_path.as_uri()

