import os
import toml
import yaml
from logging import LogRecord, getLogger

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    log_errors = []

    for filename in config_filenames:
        try:
            config = load_config_file(filename)
            if overrides:
                config = apply_overrides(config, overrides)
            if resolve_env:
                config = resolve_environment_variables(config)
            config_dict[filename] = config
        except Exception as e:
            log_error = LogRecord('load_configurations', 'ERROR', filename, 0, str(e), (), None, exc_info=True)
            log_errors.append(log_error)

    return config_dict, log_errors

def load_config_file(filename):
    if filename.endswith('.toml'):
        with open(filename) as fd:
            return toml.loads(fd.read())
    elif filename.endswith('.yaml') or filename.endswith('.yml'):
        with open(filename) as fd:
            return yaml.safe_load(fd.read())
    else:
        raise ValueError(f"Unsupported file extension: {filename}")

def apply_overrides(config, overrides):
    for key, value in overrides.items():
        keys = key.split('.')
        current_config = config
        for k in keys[:-1]:
            if k not in current_config:
                current_config[k] = {}
            current_config = current_config[k]
        current_config[keys[-1]] = value
    return config

def resolve_environment_variables(config):
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('env:'):
            env_var = value[4:]
            try:
                config[key] = os.environ[env_var]
            except KeyError:
                pass
        elif isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
        elif isinstance(value, list):
            config[key] = [resolve_environment_variables(item) if isinstance(item, dict) else item for item in value]
    return config

