class InterfaceVerificationError(Exception):
    pass

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    import inspect

    def get_implemented_interfaces(cls):
        implemented_interfaces = []
        for iface in cls.__mro__:
            if inspect.isabstract(iface):
                implemented_interfaces.append(iface)
        return implemented_interfaces

    implemented_interfaces = get_implemented_interfaces(candidate)
    for iface in implemented_interfaces:
        if iface not in iface.__subclasses__():
            if not tentative:
                raise InterfaceVerificationError(f"Interface {iface.__name__} not implemented by candidate")

