import heapq

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq = {}
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        freq = self.freq[key]
        value = self.cache[key]
        self._remove(key, freq)
        self._add(key, freq + 1, value)
        return value

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.get(key)
            self.cache[key] = value
            return
        if len(self.cache) == self.capacity:
            self._evict()
        self._add(key, 1, value)
        self.min_freq = 1

    def _remove(self, key: int, freq: int) -> None:
        heapq.heapify(self.freq[freq])
        if key in self.freq[freq]:
            self.freq[freq].remove(key)
            if not self.freq[freq]:
                del self.freq[freq]

    def _add(self, key: int, freq: int, value: int) -> None:
        if freq not in self.freq:
            self.freq[freq] = []
        heapq.heappush(self.freq[freq], key)
        self.cache[key] = value

    def _evict(self) -> None:
        to_evict = heapq.heappop(self.freq[self.min_freq])
        del self.cache[to_evict]
        del self.freq[self.min_freq]
        self.min_freq = min(self.freq.keys())

