def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import copy
    import utool as ut

    def resolve_include(include_dict):
        """
        Recursively resolves the include directive in the include_dict.
        """
        resolved = {}
        for key, value in include_dict.items():
            if key == 'include':
                resolved.update(resolve_include(value))
            elif isinstance(value, dict):
                resolved[key] = resolve_include(value)
            else:
                resolved[key] = value
        return resolved

    def merge_dicts(dict1, dict2):
        """
        Merges dict2 into dict1. If there are overlapping keys, dict2's value will overwrite dict1's.
        """
        for key, value in dict2.items():
            if isinstance(value, dict) and key in dict1 and isinstance(dict1[key], dict):
                merge_dicts(dict1[key], value)
            else:
                dict1[key] = copy.deepcopy(value)

    for section, options in parser_dict.items():
        if section == 'include':
            resolved_include = resolve_include(options)
            merge_dicts(parser_dict, resolved_include)

    return parser_dict

